package com.hbm.machine.forcefield;
import com.mojang.serialization.MapCodec;import java.util.Random;import net.minecraft.core.*;import net.minecraft.core.particles.*;import net.minecraft.world.*;import net.minecraft.world.entity.item.ItemEntity;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.entity.*;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.phys.BlockHitResult;
/** Original single full collision cube, nonopaque, BER body extending above it; no fabricated multiblock proxies. */
public final class ForceFieldBlock extends BaseEntityBlock {
 private final Random dropRandom=new Random();
 public ForceFieldBlock(){super(Properties.of().strength(5,60).sound(SoundType.STONE).requiresCorrectToolForDrops().noOcclusion());}
 @Override protected MapCodec<? extends ForceFieldBlock> codec(){return MapCodec.unit(this);}@Override protected RenderShape getRenderShape(BlockState state){return RenderShape.ENTITYBLOCK_ANIMATED;}
 @Override protected int getLightBlock(BlockState state,BlockGetter level,BlockPos pos){return 0;}@Override protected boolean propagatesSkylightDown(BlockState state,BlockGetter level,BlockPos pos){return true;}
 @Override public BlockEntity newBlockEntity(BlockPos pos,BlockState state){return new ForceFieldBlockEntity(pos,state);}@Override public <T extends BlockEntity> BlockEntityTicker<T> getTicker(Level level,BlockState state,BlockEntityType<T> type){return createTickerHelper(type,ForceFieldContent.ENTITY.get(),ForceFieldBlockEntity::tick);}
 @Override protected InteractionResult useWithoutItem(BlockState state,Level level,BlockPos pos,Player player,BlockHitResult hit){if(!level.isClientSide&&!player.isShiftKeyDown()&&level.getBlockEntity(pos) instanceof ForceFieldBlockEntity field)player.openMenu(field,pos);return InteractionResult.sidedSuccess(level.isClientSide);}
 @Override protected void onRemove(BlockState state,Level level,BlockPos pos,BlockState replacement,boolean moved){if(!state.is(replacement.getBlock())){if(!level.isClientSide&&level.getBlockEntity(pos) instanceof ForceFieldBlockEntity field){for(int slot=0;slot<field.getContainerSize();slot++){var stack=field.getItem(slot);if(stack.isEmpty())continue;float x=dropRandom.nextFloat()*.8F+.1F,y=dropRandom.nextFloat()*.8F+.1F,z=dropRandom.nextFloat()*.8F+.1F;while(!stack.isEmpty()){int count=Math.min(dropRandom.nextInt(21)+10,stack.getCount());var dropped=stack.split(count);var item=new ItemEntity(level,pos.getX()+x,pos.getY()+y,pos.getZ()+z,dropped);item.setDeltaMovement((float)dropRandom.nextGaussian()*.05F,(float)dropRandom.nextGaussian()*.05F+.2F,(float)dropRandom.nextGaussian()*.05F);level.addFreshEntity(item);}}level.updateNeighbourForOutputSignal(pos,this);}super.onRemove(state,level,pos,replacement,moved);}}
 @Override public void animateTick(BlockState state,Level level,BlockPos pos,net.minecraft.util.RandomSource random){if(!(level.getBlockEntity(pos) instanceof ForceFieldBlockEntity field))return;if(field.isOn&&field.cooldown==0&&field.power.signum()>0)for(int i=0;i<4;i++)level.addParticle(field.color==0xff0000?ParticleTypes.LAVA:DustParticleOptions.REDSTONE,pos.getX()+random.nextFloat(),pos.getY()+2F,pos.getZ()+random.nextFloat(),0,0,0);else if(field.cooldown>0)for(int i=0;i<4;i++)level.addParticle(ParticleTypes.SMOKE,pos.getX()+random.nextFloat(),pos.getY()+2F,pos.getZ()+random.nextFloat(),0,0,0);}
}
